from author_helpers import Draft
b=Draft(24)
b.concept('selected_compute_notation','Selected compute notation','fn<A,B>.C is notation over a published GraphFunction bound by Job, optionally a realized GraphVector context, and a selected abg.fn_composition identity. C denotes selected composition, not a new callable or runtime entity.',[(0,94,98)])
b.concept('transform_phase','transform.C','Candidate and evidence production under a selected composition, including plugin.transform.C computation.',[(0,100,100),(0,122,122)])
b.concept('evaluation_phase','evaluate.C','Evaluation-set phase whose rules produce proposed deterministic registers, semantic findings, gain, metrics, close dispositions, residual pressure, continuation/evidence/authority references and diagnostics.',[(0,102,102)])
b.concept('abg_admission','ABG admission','The epistemic boundary at which candidate/evaluation data becomes runtime fact; ABG owns payload and event admission and the associated runtime truth surfaces.',[(0,104,104),(0,114,114)])
b.concept('consequence_projection','consequence.C','Projection over ABG-admitted state, assurance decisions, traversal transitions and downstream read models, computed as plugin.consequence.C without independent runtime mutation authority.',[(0,106,106),(0,122,122)])
b.concept('traversal_unit','TraversalUnit<A,B>','Notation for one closeable traversal atom under selected GraphFunction execution, internal GraphVector, composition, admitted attempt envelope and stage outputs, assurance fold, consequence, transition and replay; not a new topology, public call, callback, overlay, registry, command or controller.',[(0,144,144)])
b.concept('context','Context','First-class language-owned declaration of an externally located snapshot-bound constraint dimension carried by graph structure, binding at least name, locator and digest.',[(2,13,14),(3,18,24)])
b.concept('frame_work_contract','Reusable frame work/evaluation contract','Existing Context, contract and policy declarations selected by a graph composition that bind owning frame definition, exact subject/basis, observations, criteria, authority, evidence, result relation and invalidators.',[(3,54,60)])
b.concept('contract_law_reload','GTL contract-law reload surface','Navigation surface for exact boundaries among GTL, validator, HoG, ABG, implementation seams and downstream Products; it indexes and does not replace detailed requirements or complete Product definition.',[(5,12,15)])
b.constraint('ontology_names_preserved',['selected_compute_notation'],'Preserve Graph, Node, GraphVector, Context, Operator, Evaluator, Rule, GraphFunction, RefinementBoundary, CandidateFamily, ContractRef, Role, Job, Module and abg.fn_composition names. Do not introduce ComputeUnit, ReliableCompute, topology anchor, public callable, runtime carrier or execution target through notation.',[(0,92,96)])
b.constraint('selected_composition_binding',['selected_compute_notation'],'Preserve composition contract reference, digest, host binding, declaration source, ordered regime bindings, standards/policy/carrier/assurance context, deterministic closure contract and optimization contract when present. Distinguish owning selected host from source; hooks, visible defaults, policy hooks and templates may source a selection but cannot appear as owning hosts. Evaluation, admitted-state and consequence notation participating in a governed boundary must carry selected ref/digest or a causally linked selection reference.',[(0,98,98),(0,108,108),(0,112,112)],conditions=['Optimization contract is preserved when present.','Participation in an abg.fn_composition boundary requires selection provenance.'])
b.constraint('compute_non_authority',['transform_phase','evaluation_phase','consequence_projection'],'Transform produces candidate/evidence only, with no event, ledger, traversal or closure authority. Evaluation produces proposed findings and values only, with no direct close, write, selection, transition or emission of runtime truth. Consequence is projection, not an independent action stage mutating runtime truth. Plugin/evaluator returns before admission are proposed evidence and not event, ledger, projection, traversal or closure truth.',[(0,100,106)])
b.constraint('closure_fibre_boundary',['selected_compute_notation'],'Regime notation makes non-F_D closure authority unrepresentable. F_P/F_H may construct, diagnose, repair, rank, provide evidence, judge, escalate or stand absentia under ABG law, but may not claim closure authority.',[(0,110,110)])
b.constraint('runtime_owner_partition',['selected_compute_notation','abg_admission'],'HoG owns direct GTL traversal mechanics. ABG owns events, payload admission, ledger projection, assurance fold, admitted transitions, continuation, closure, correction and replay. Compute notation may reference but cannot write these. ABG.system effects occur between plugin compute categories: only ABG.system admits values, writes events, derives ledgers, folds assurance, admits transitions, replays continuation or closes; HoG alone advances admitted topology.',[(0,114,114),(0,126,130)])
b.constraint('product_projection_meaning',['consequence_projection'],'Product-specific pressure, gain semantics and read-model interpretation remain Product-owned projections over ABG-admitted facts. GTL notation does not standardize downstream strategy. Documentation, examples and tenant contracts must describe Composition(...) as display shorthand for selected abg.fn_composition, never separate truth.',[(0,116,118)])
b.constraint('plugin_category_contract',['transform_phase','evaluation_phase','consequence_projection'],'Expose transform/evaluate/consequence plugin categories preserving composition reference/digest/selection reference, regime-binding reference when present, input/output carrier and evidence references, and non-authority flags for ledger/event/traversal/closure prohibition. Public observer and hook/action surfaces use plugin.transform.C, plugin.evaluate.C and plugin.consequence.C with their specific candidate, rule-computation and projection meanings instead of ambiguous eval.',[(0,120,122)],conditions=['Preserve a regime-binding reference when present.'])
b.constraint('human_external_response',['selected_compute_notation','abg_admission'],'An F_H composition participant is an external human-callout compute category that requires F_H, states that human work is outside ABG and requires response admission before any human result affects runtime truth.',[(0,124,124)],conditions=['F_H participates in composition.'])
b.constraint('same_law_reductions',['selected_compute_notation','evaluation_phase'],'A fully F_D graph is a lawful deterministic event-sourced reduction of the same composition identity and ABG admission/events/replay, with no separate API or shortcut. Scalar FpEvaluationOutcome is a one-rule evaluate.C reduction, not another carrier or Product loop. Every composed C stage is representable as a stage-set phase; scalar transform/evaluate/consequence calls are one-task reductions, never privileged alternate paths.',[(0,132,132),(0,140,142)])
b.constraint('evaluation_rule_admission_order',['evaluation_phase','abg_admission'],'When declared, evaluate.C.F_D.register_rule[*] is first-class work deriving read-only shape, lineage, coverage, target-carrier, observed-state and domain registers whose results await ABG admission. When ambiguity remains, F_P semantic rules evaluate admitted transform truth plus admitted registers and may propose disposition/residual pressure; closure remains ABG assurance fold. Ordered or parallel rule batches operate only on read-only admitted facts. Replay identity comes from composition, declared rule references, batch/dependency references and admitted outcomes, never wall-clock completion order.',[(0,134,138)],conditions=['Deterministic register rules must be declared by the selection.','F_P semantic judgment applies when ambiguity remains.'])
b.constraint('consequence_bind_ownership',['consequence_projection','traversal_unit'],'Consequence bind consists of plugin.consequence.C plus ABG consequence admission, traversal transition and replay continuation. The plugin alone owns neither bind, transition, replay, closure nor next-unit selection.',[(0,146,146)])
b.constraint('intent_lineage_function_law',['traversal_unit'],'The traversal atom can be interpreted as traverse<A,B>(intent_lineage, context, A) -> (B, obligation_delta), a law over existing carriers, not a callable API. Intent lineage includes admitted intent/lineage, source/target carrier, materialization/output-allocation, carried obligation, residual pressure and lawful basis references. Each carried obligation receives an explicit delta: realized, refined, deferred to a named downstream unit, blocked, repriced, preserved as no-close pressure or discharged by terminal truth.',[(0,148,148)])
b.constraint('consequence_obligation_conservation',['traversal_unit','consequence_projection'],'Preserve lineage and obligations across unit composition. Close/next-unit selection is nonconforming if a carried obligation, target binding, materialization target, role requirement, staged authority reference or downstream terminal pressure disappears without admitted realization evidence, refinement, downstream deferral, block, re-entry, reprice, no-close preservation or terminal projection.',[(0,150,150)])
b.relation('transform_proposes_for_admission','proposes_evidence_to','transform_phase','abg_admission','Candidate and evidence production reaches runtime truth only through ABG admission.',[(0,100,104)],True)
b.relation('evaluation_proposes_for_admission','proposes_findings_to','evaluation_phase','abg_admission','Evaluation returns remain proposals until admitted; the phase does not directly close or mutate truth.',[(0,102,104)],True)
b.relation('consequence_reads_admitted_truth','projects_from','consequence_projection','abg_admission','Consequence projects only ABG-admitted state and linked assurance/transition truth.',[(0,106,106)],False)
b.constraint('context_identity_and_preservation',['context'],'Context is language declaration truth, not an engine event/runtime fact. Publication and interpretation preserve locator/digest without semantic loss. Engines may load, validate or project but cannot invent or mutate the contract.',[(3,18,28)])
b.constraint('workspace_observation_currentness',['context'],'Governance-graph workspace evidence identifies declared workspace subject and immutable observation basis. The locator/digest pins observed material, not the mutable workspace itself. Historical admitted observations do not prove current state without applicable support. Prompt-only locators and private workspace handles cannot replace the declared relation.',[(3,30,35)])
b.constraint('explicit_stdo_environment',['context'],'An STDO-governed Program explicitly selects reusable GTL environment and snapshot Context with exact immutable release/content basis, native material, acquisition permission and required access evidence, and role-specific frame/instruction policy references. Supplements are required only if explicitly selected and must preserve exact released identity, source relationship, access contract and required evidence. Publication/raw admission/interpretation conserve those relations. Mutable selectors, ambient installs, available tools, source-development composition and instruction prose do not substitute. Declaration grants neither access nor runtime admission; optional environment selection does not make its required contents/evidence optional.',[(3,37,52)],conditions=['Program adopts the STDO-governed environment.','A supplement becomes required only when explicitly selected.'],exceptions=['Programs not adopting the environment acquire no implicit STDO requirement.'])
b.constraint('explicit_frame_binding',['frame_work_contract','context'],'A framed call binds its reusable contract explicitly through graph-selected Context/contract/policy declarations and preserves every listed element. Rendered prompt is projection only; role name, overlay row or runtime Frame identity alone is insufficient.',[(3,54,60)])
b.constraint('frame_selection_and_missing_evidence',['frame_work_contract'],'Frame selection is declared or follows prior admitted selection under Program policy. Missing-observation acquisition is declared work. Unknown applicability, missing required evidence, out-of-frame material and invalid basis remain explicit dispositions; assembly cannot infer pass or silently omit an applicable required evaluation.',[(3,62,67)])
b.constraint('multiple_frames_and_reuse',['frame_work_contract'],'Separate frames keep separate definitions, evidence and authority. Relied-on refinement, translation, conjunction and dependency are explicit; graph nesting alone gives no hierarchy, precedence or sufficiency. Material frame/subject/observation changes invalidate dependent support before reuse while preserving unaffected support. Select sufficient bounded material and current admitted projections under Product reuse law; a role handoff alone does not require full-history reconstruction or workspace scans.',[(3,69,78)])
b.relation('frame_contract_uses_context','binds_through','frame_work_contract','context','Existing selected Context declarations participate in the explicit reusable frame contract binding.',[(3,54,60)],True)
b.constraint('reload_governing_chain',['contract_law_reload'],'The declared governing chain is GTL.TypeScript -> native type/raw admission -> non-lowering GTL validation -> module/catalog admission -> direct HoG traversal -> declared F_D/F_P/F_H seam -> ABG admission/events/replay/continuation/closure. The summary does not replace detailed requirement families or Product law.',[(5,12,26)])
b.residual('indexed_law_dependency','contract_law_reload','The index names language/identity, program structure, graph/C algebra, declaration boundaries, traversal mapping and ABG runtime families whose complete laws are not contained here.','Follow those exact sources for detailed meaning and do not infer dependencies or identity from shared labels.',[(6,31,46)])
b.residual('frame_policy_dependency','frame_work_contract','Owning frame definitions, admitted selection, Product reuse law and environment-specific evidence/access policies are referenced but not instantiated by these generic declarations.','No current frame evaluation, permission, sufficiency or reuse verdict follows merely from this representation.',[(3,37,78)])
